<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class AssignTransportPassengerRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('transporte.rutas.gestionar')??false;}public function rules():array{$company=$this->user()->company_id;return['transport_passenger_id'=>['required',Rule::exists('transport_passengers','id')->where(fn($q)=>$q->where('company_id',$company))],'transport_route_stop_id'=>'nullable|exists:transport_route_stops,id','direction'=>['required',Rule::in(array_keys(config('transport.directions')))],'valid_from'=>'required|date','valid_until'=>'nullable|date|after_or_equal:valid_from','status'=>'required|in:active,inactive'];}public function withValidator($validator):void{$validator->after(function($v){$route=$this->route('transportRoute');if(!$route||!$this->filled('transport_passenger_id')||!$this->filled('direction')||!$this->filled('valid_from'))return;$exists=$route->passengers()->wherePivot('direction',$this->input('direction'))->wherePivot('valid_from',$this->input('valid_from'))->where('transport_passengers.id',$this->input('transport_passenger_id'))->exists();if($exists){$v->errors()->add('transport_passenger_id','Este pasajero ya está asignado a esta ruta con la misma dirección y fecha de vigencia.');return;}$newFrom=$this->input('valid_from');$newUntil=$this->input('valid_until')?:'9999-12-31';$overlaps=$route->passengers()->wherePivot('status','active')->where('transport_passengers.id',$this->input('transport_passenger_id'))->get()->contains(function($p)use($newFrom,$newUntil){$existingFrom=$p->pivot->valid_from;$existingUntil=$p->pivot->valid_until?:'9999-12-31';return$existingFrom<=$newUntil&&$existingUntil>=$newFrom;});if($overlaps)$v->errors()->add('transport_passenger_id','Este pasajero ya tiene una asignación activa en esta ruta que se cruza en fechas con la nueva. Retire o ajuste la vigencia de la asignación anterior antes de continuar.');});}}
